import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;

public final class ActivitySelection {
    private ActivitySelection() {
    }

    public static int activitySelection(int[] start, int[] finish) {
        return optimalSchedule(start, finish).size();
    }

    public static int activitySelection(Activity[] activities) {
        return optimalSchedule(activities).size();
    }

    public static int activitySelection(List<Activity> activities) {
        return optimalSchedule(activities).size();
    }

    public static List<Activity> selectActivities(int[] start, int[] finish) {
        return optimalSchedule(start, finish).activities();
    }

    public static List<Activity> selectActivities(Activity[] activities) {
        return optimalSchedule(activities).activities();
    }

    public static List<Activity> selectActivities(List<Activity> activities) {
        return optimalSchedule(activities).activities();
    }

    public static Schedule optimalSchedule(int[] start, int[] finish) {
        return Problem.fromArrays(start, finish).optimalSchedule();
    }

    public static Schedule optimalSchedule(Activity[] activities) {
        return Problem.fromArray(activities).optimalSchedule();
    }

    public static Schedule optimalSchedule(List<Activity> activities) {
        return Problem.of(activities).optimalSchedule();
    }

    public static record Activity(int start, int finish) {
        public static List<Activity> fromArrays(int[] start, int[] finish) {
            Objects.requireNonNull(start, "start must not be null");
            Objects.requireNonNull(finish, "finish must not be null");

            if (start.length != finish.length) {
                throw new IllegalArgumentException("start and finish must have the same length");
            }

            List<Activity> activities = new ArrayList<>(start.length);
            for (int i = 0; i < start.length; i++) {
                activities.add(new Activity(start[i], finish[i]));
            }
            return List.copyOf(activities);
        }

        public Activity {
            if (finish < start) {
                throw new IllegalArgumentException("finish must be greater than or equal to start");
            }
        }

        public boolean canFollow(Activity other) {
            Objects.requireNonNull(other, "other must not be null");
            return start >= other.finish;
        }
    }

    private static record Problem(List<Activity> activities) {
        private static final Comparator<Activity> BY_FINISH_TIME =
            Comparator.comparingInt(Activity::finish).thenComparingInt(Activity::start);

        private Problem {
            activities = copyActivities(activities);
        }

        private static Problem fromArrays(int[] start, int[] finish) {
            return new Problem(Activity.fromArrays(start, finish));
        }

        private static Problem fromArray(Activity[] activities) {
            Objects.requireNonNull(activities, "activities must not be null");
            return new Problem(Arrays.asList(activities));
        }

        private static Problem of(List<Activity> activities) {
            return new Problem(activities);
        }

        private Schedule optimalSchedule() {
            if (activities.isEmpty()) {
                return Schedule.empty();
            }

            return Schedule.fromSortedActivities(sortedByFinishTime());
        }

        private List<Activity> sortedByFinishTime() {
            List<Activity> sortedActivities = new ArrayList<>(activities);
            sortedActivities.sort(BY_FINISH_TIME);
            return sortedActivities;
        }

        private static List<Activity> copyActivities(List<Activity> activities) {
            Objects.requireNonNull(activities, "activities must not be null");

            List<Activity> copiedActivities = new ArrayList<>(activities.size());
            for (int i = 0; i < activities.size(); i++) {
                copiedActivities.add(
                    Objects.requireNonNull(activities.get(i), "activities[" + i + "] must not be null")
                );
            }

            return List.copyOf(copiedActivities);
        }
    }

    public static record Schedule(List<Activity> activities) {
        private static Schedule fromSortedActivities(List<Activity> sortedActivities) {
            List<Activity> selectedActivities = new ArrayList<>();
            Activity lastSelected = sortedActivities.get(0);
            selectedActivities.add(lastSelected);

            for (int i = 1; i < sortedActivities.size(); i++) {
                Activity candidate = sortedActivities.get(i);
                if (candidate.canFollow(lastSelected)) {
                    lastSelected = candidate;
                    selectedActivities.add(lastSelected);
                }
            }

            return new Schedule(selectedActivities);
        }

        public Schedule {
            activities = List.copyOf(Objects.requireNonNull(activities, "activities must not be null"));
        }

        public static Schedule empty() {
            return new Schedule(List.of());
        }

        public int size() {
            return activities.size();
        }
    }

    public static void main(String[] args) {
        int[] start = {1, 3, 0, 5, 8, 5};
        int[] finish = {2, 4, 6, 7, 9, 9};

        System.out.println(activitySelection(start, finish));
    }
}

